"""
Script to reproduce the boolean literal issue in auto-generated docstrings.
"""

import json
from dash.development._py_components_generation import create_docstring

def test_boolean_defaults_in_docstrings():
    """Test that boolean defaults are properly converted to Python format."""

    # Mock component data similar to the flow test data
    component_props = {
        "optionalBoolean": {
            "required": False,
            "description": "A boolean test",
            "flowType": {
                "name": "boolean"
            },
            "defaultValue": {
                "value": "false",  # This should become "False" in docstring
                "computed": False
            }
        },
        "anotherBoolean": {
            "required": False,
            "description": "Another boolean test",
            "flowType": {
                "name": "boolean"
            },
            "defaultValue": {
                "value": "true",  # This should become "True" in docstring
                "computed": False
            }
        }
    }

    # Generate docstring
    docstring = create_docstring(
        component_name="TestComponent",
        props=component_props,
        description="A test component with boolean defaults."
    )

    print("Generated docstring:")
    print("=" * 50)
    print(docstring)
    print("=" * 50)

    # Check if the issue exists
    if "default false" in docstring:
        print("❌ ISSUE FOUND: 'false' found in docstring (should be 'False')")
    else:
        print("✅ No 'false' found")

    if "default true" in docstring:
        print("❌ ISSUE FOUND: 'true' found in docstring (should be 'True')")
    else:
        print("✅ No 'true' found")

    if "default False" in docstring:
        print("✅ Correct 'False' found in docstring")
    else:
        print("❌ Missing 'False' in docstring")

    if "default True" in docstring:
        print("✅ Correct 'True' found in docstring")
    else:
        print("❌ Missing 'True' in docstring")

if __name__ == "__main__":
    test_boolean_defaults_in_docstrings()"}

